import csv
from datetime import date, datetime
from collections import defaultdict

def top_n_customers(
    path: str,
    n: int = 5,
    year_quarter: tuple[int, int] = (2026, 1),
) -> list[dict]:
    year, q = year_quarter
    q_starts = {1: (1, 1), 2: (4, 1), 3: (7, 1), 4: (10, 1)}
    q_ends = {1: (3, 31), 2: (6, 30), 3: (9, 30), 4: (12, 31)}
    start = date(year, *q_starts[q])
    end = date(year, *q_ends[q])

    totals: dict[str, float] = defaultdict(float)
    with open(path, encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        # Normalize headers — strip stray whitespace.
        reader.fieldnames = [name.strip() for name in (reader.fieldnames or [])]
        for i, row in enumerate(reader, start=2):
            try:
                d = datetime.strptime(row['date'].strip(), '%Y-%m-%d').date()
                amount = float(row['amount'])
                customer = row['customer'].strip()
            except (KeyError, ValueError) as e:
                raise ValueError(f'Row {i} malformed: {row}; {e}') from e
            if start <= d <= end and amount > 0:
                totals[customer] += amount

    top = sorted(totals.items(), key=lambda kv: -kv[1])[:n]
    return [{'customer': c, 'total': round(t, 2)} for c, t in top]
